import "server-only";
import { createReadStream } from "node:fs";
import { mkdir, readFile, rename, rm, stat, statfs, writeFile } from "node:fs/promises";
import os from "node:os";
import path from "node:path";

/**
 * Local-disk storage for uploads. Files live OUTSIDE the app folder (which is
 * replaced on every deploy): UPLOAD_DIR, or ~/digitalsminds-uploads by default.
 * Keys are generated by the server; resolve() still refuses anything that
 * could escape the root.
 */

export function uploadRoot(): string {
  const configured = process.env.UPLOAD_DIR?.trim();
  return path.resolve(configured || path.join(os.homedir(), "digitalsminds-uploads"));
}

const KEY_RE = /^[a-z0-9][a-z0-9/_.-]{0,480}$/;

/** Absolute path for a storage key, or throws if the key is unsafe. */
export function resolveKey(key: string, root = uploadRoot()): string {
  if (!KEY_RE.test(key) || key.includes("..") || key.includes("//") || key.endsWith("/")) {
    throw new Error("Invalid storage key");
  }
  const full = path.resolve(root, key);
  if (!full.startsWith(root + path.sep)) throw new Error("Invalid storage key");
  return full;
}

export async function putFile(key: string, data: Buffer, root?: string) {
  const full = resolveKey(key, root);
  await mkdir(path.dirname(full), { recursive: true });
  // Write to a temp file first so a crash never leaves a half-written upload.
  const tmp = `${full}.${process.pid}.${Date.now()}.tmp`;
  await writeFile(tmp, data, { mode: 0o640 });
  await rename(tmp, full);
}

export async function fileExists(key: string, root?: string) {
  try {
    return (await stat(resolveKey(key, root))).isFile();
  } catch {
    return false;
  }
}

export function readStream(key: string, root?: string) {
  return createReadStream(resolveKey(key, root));
}

export async function deleteFile(key: string, root?: string) {
  await rm(resolveKey(key, root), { force: true });
}

/** Free space on the disk holding the uploads (hosting quotas may be lower). */
export async function freeBytes(root = uploadRoot()): Promise<number | null> {
  try {
    const s = await statfs(root);
    return s.bavail * s.bsize;
  } catch {
    return null;
  }
}

export { mkdir, readFile, writeFile };
